mapper.select:
SELECT * FROM todo

    AND completed = #{completed}
    AND tags LIKE '%' || #{tag} || '%'
    AND priority = #{priority}
    AND is_favorite = #{isFavorite}
    AND is_archived = #{isArchived}

        AND is_deleted = 1
        AND is_deleted = 0

    AND (owner_id = #{ownerId} OR shared_with LIKE '[%' || #{ownerId} || '%]')

ORDER BY updated_at DESC

mapper.update:
UPDATE todo SET is_archived = 0, is_deleted = 0, deleted_at = NULL,
    updated_at = datetime('now','localtime')
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM todo
WHERE created_at >= #{start} AND created_at <= #{end}
  AND owner_id = #{ownerId}

SELECT COUNT(*) FROM todo
WHERE completed = 1
  AND updated_at >= #{start} AND updated_at <= #{end}
  AND owner_id = #{ownerId}

SELECT COUNT(*) FROM todo
WHERE priority = #{priority}
  AND created_at >= #{start} AND created_at <= #{end}
  AND owner_id = #{ownerId}

SELECT * FROM todo_completion_log
WHERE todo_id = #{todoId}
ORDER BY completed_at DESC

SELECT cl.* FROM todo_completion_log cl
INNER JOIN todo t ON cl.todo_id = t.id
WHERE cl.completed_at >= #{start, typeHandler=xyz.crearts.note.keeper.mapper.typehandler.LocalDateTimeTypeHandler}
  AND cl.completed_at <= #{end, typeHandler=xyz.crearts.note.keeper.mapper.typehandler.LocalDateTimeTypeHandler}
  AND t.owner_id = #{ownerId}
  AND t.is_deleted = 0
ORDER BY cl.completed_at DESC

mapper.update:
UPDATE todo SET
    last_completed_at = #{lastCompletedAt, typeHandler=xyz.crearts.note.keeper.mapper.typehandler.LocalDateTimeTypeHandler},
    updated_at = #{lastCompletedAt, typeHandler=xyz.crearts.note.keeper.mapper.typehandler.LocalDateTimeTypeHandler}
WHERE id = #{id}

mapper.delete:
DELETE FROM todo_completion_log
WHERE todo_id = #{todoId}
  AND completed_at >= #{since, typeHandler=xyz.crearts.note.keeper.mapper.typehandler.LocalDateTimeTypeHandler}
